 *
 * @param headers The string containing the headers, which are being parsed.
 * @return An array of headers, where each element is a colon-separated name and value pair.
 * @throws IllegalStateException If the headers cannot be parsed.
 */
private string[] parseHeaders(string headers) {
  string[] headersArr = new string[10];
  int end = 0;
  int start = 0;
  for (int i = 0; i < headers.Length; i++) {
    if (headers[i] == '\r') {
      headersArr[end] = headers.Substring(start, i - start);
      start = i + 2;
      end++;
    }
  }
  if (end == 0)
    throw new IllegalStateException("Headers cannot be parsed.");
  return headersArr;
}

