public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings result = new Mappings();
    for (Index index : mappings.getIndices()) {
        if (!index.getTable_name().equals(tableName)) {
            // excludes mappings from current index
            continue;
        }
        Index newIndex = new Index();
        newIndex.setTable_name(tableName);
        List<Field> fields = newIndex.getFields();
        for (Field field : index.getFields()) {
            if (field.getSource() == null || field.getName() == null) {
                // excludes illegal configurations
                continue;
            }
            fields.add(new Field(field.getName(), field.getSource().replace("_current", ""), field.getType()));
        }
        result.add(newIndex);
    }
    return result;
}

