    // Create a new list to store the loaded thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Check if the file exists and is not a directory
    if (file.isFile()) {
        // Create a new buffered reader to read the file
        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file)), 1024 * 1024);

        // Read and parse each line of the file
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line to extract the thread name and the time range
            String[] fields = line.split(",");
            String threadName = fields[0];
            long startTime = Long.parseLong(fields[1]);
            long endTime = Long.parseLong(fields[2]);

            // Check if the current time range is within the specified range
            boolean withinRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (startTime >= timeRange.startTime && endTime <= timeRange.endTime) {
                    withinRange = true;
                    break;
                }
            }

            // If the current time range is within the specified range, create a new thread snapshot and add it to the list
            if (withinRange) {
                ThreadSnapshot snapshot = new ThreadSnapshot(threadName, startTime, endTime);
                threadSnapshots.add(snapshot);
            }
        }

        // Close the buffered reader
        reader.close();
    }

    // Return the list of thread snapshots
    return threadSnapshots;
